-- Generated by `pnpm --filter @carbon/database authz migration` from packages/database/src/authz. Do not edit.

-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.sync_insert_company_related_records(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation != 'INSERT' THEN RETURN; END IF;

  INSERT INTO "terms" ("id")
  VALUES (p_new->>'id');

  -- Metric unless the company is in the US or one of its territories. A
  -- company with no country falls back to its base currency. seedCompany
  -- reads this to pick the units of measure it seeds.
  INSERT INTO "companySettings" ("id", "useMetric")
  VALUES (
    p_new->>'id',
    CASE
      WHEN NULLIF(p_new->>'countryCode', '') IS NOT NULL
        THEN upper(p_new->>'countryCode') NOT IN ('US', 'AS', 'GU', 'MP', 'PR', 'UM', 'VI')
      ELSE COALESCE(NULLIF(p_new->>'baseCurrencyCode', ''), 'USD') <> 'USD'
    END
  );
END;
$function$;
